CREATE TABLE IF NOT EXISTS model3_training_data (
    row_id        INT AUTO_INCREMENT PRIMARY KEY,
    feature_vector JSON NOT NULL,
    crop_label    VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS model3_observations (
    row_id            INT AUTO_INCREMENT PRIMARY KEY,
    CROPS             VARCHAR(100) NOT NULL,
    TYPE_OF_CROP      VARCHAR(100),
    TEMPERATURE       DOUBLE,
    SEASON            VARCHAR(50),
    SOWN              VARCHAR(50),
    HARVESTED         VARCHAR(50),
    WATER_SOURCE      VARCHAR(100),
    RELATIVE_HUMIDITY DOUBLE,
    N                 INT,
    P                 INT,
    K                 INT
);

